"""Interface definitions."""

import abc
import typing

from jsilib import _utils
from jsilib.base import IClosable
from jsilib.jsi.interface import IJSIMessage

from .messages import SID, JSONRPCMessage, JSONRPCNotif, JSONRPCRequest, JSONRPCResponse

__all__ = export = _utils.ExportList(
    ['JSONRPCRequestMessage', 'JSONRPCResponseMessage', 'JSONRPCNotifMessage', 'MethodHandlerReturnType']
)

JSONRPCResponseMessage = JSONRPCMessage[JSONRPCResponse]
JSONRPCRequestMessage = JSONRPCMessage[JSONRPCRequest]
JSONRPCNotifMessage = JSONRPCMessage[JSONRPCNotif]
MethodHandlerReturnType = typing.Union[JSONRPCResponseMessage, typing.Any]


@export
class IJSONRPCNotifier(abc.ABC):
    """Base class for JSONRPC notification producers."""

    @abc.abstractmethod
    async def notify(self, method: str, params: typing.Any = None, sid: SID = None, body: IJSIMessage = None):
        """Send notification message.

        :param method:
            Notification's method (or subject)

        :param params:
            Notification's parameters (optional)

        :param sid:
            Session ID (optional)

        :param body:
            Binary payload to be sent with notification message (optional)
        """


@export
class IJSONRPCSubscriber(abc.ABC):
    """Base class for JSONRPC notification consumers."""

    @abc.abstractmethod
    def subscribe(self, subscriber: typing.Coroutine, method: str, sid: SID = None) -> int:
        """Register *subscriber* as notification listener and return
        subscription ID.

        Registered *subscriber* must be a coroutine that accepts
        :class:`Message` object, having :class:`Notification` object as a head.

        The ID returned by this method can later be passed to
        :meth:`unsubscribe` method.

        :param subscriber:
            Subscriber coroutine function to be registered

        :param method:
            Method name (or subject) to subscribe to

        :param sid:
            Session ID to subscribe to (optional)

            If this is set while subscribing, then subscriber will only be
            triggered when notification having the same *method* and *sid* is
            received. Otherwise only *method* is used during comparison.
        """

    @abc.abstractmethod
    def unsubscribe(self, subscriber_id: int) -> bool:
        """Unsubscribe subscriber matching given *id*.

        If passed *id* is valid, then remove matching subscription and return
        ``True``. Otherwise return ``False``.

        :param subscriber_id:
            Subscription ID returned by :meth:`subscribe`
        """


@export
class IJSONRPCClient(IClosable, IJSONRPCSubscriber):
    """Base class for JSONRPC protocol clients."""

    @abc.abstractmethod
    async def execute(self,
                      method: str,
                      params: typing.Any = None,
                      sid: SID = None,
                      body: IJSIMessage = None) -> JSONRPCMessage[JSONRPCResponse]:
        """Execute remote procedure and await for response.

        :param method:
            Remote method name

        :param params:
            Remote method parameters (optional)

        :param sid:
            Session ID to pass to remote method handler (optional)

        :param body:
            Binary payload to be sent to remote method handler (optional)
        """


@export
class IMethodHandlerContext(abc.ABC):
    """Base class for method handler context objects.

    Instances of this class are passed to method handlers registered to the
    server. See :meth:`IJSONRPCServer.register_method` for more details.
    """

    @property
    @abc.abstractmethod
    def server_notifier(self) -> IJSONRPCNotifier:
        """A notifier that allows to send notifications to all connected
        clients."""

    @property
    @abc.abstractmethod
    def connection_notifier_factory(self) -> typing.Callable[[], typing.Optional[IJSONRPCNotifier]]:
        """A factory function returning notifier that can be used to notify
        connection from which the request was sent.

        This can be used in application layer to perform more sophisticated
        notifications. The function provided by this property will return a
        notifier object for as long as underlying connection is alive. If
        connection is no longer available, a ``None`` will be returned.
        """

    @property
    @abc.abstractmethod
    def globals(self) -> dict:
        """Access server's globals."""

    @property
    @abc.abstractmethod
    def request(self) -> JSONRPCMessage[JSONRPCRequest]:
        """Request data."""


@export
class IMethodHandlerRegistry(abc.ABC):
    """Base class for method handler registries."""
    MethodHandlerType = typing.Callable[[IMethodHandlerContext], typing.Coroutine[None, None, MethodHandlerReturnType]]

    @abc.abstractmethod
    def find_method(self, name: str) -> typing.Optional[MethodHandlerType]:
        """Perform a lookup of a method handler.

        If handler is not found, then return ``None``. Otherwise return
        registered handler.

        This method performs a lookup using method's full name (i.e. the name
        that is sent via JSONRPC request).

        :param name:
            A full name of a method to get.
        """

    @abc.abstractmethod
    def list_methods(self) -> typing.Iterator[typing.Tuple[str, MethodHandlerType]]:
        """Return an iterator over methods registered directly to this object
        via :meth:`register_method` method."""

    @abc.abstractmethod
    def list_namespaces(self) -> typing.Iterator[typing.Tuple[str, 'IMethodHandlerRegistry']]:
        """Return an iterator over namespaces registered directly to this
        object via :meth:`register_namespace` method."""

    @abc.abstractmethod
    def register_method(self, name: str, handler: MethodHandlerType):
        """Attach a method handler to this namespace.

        If *name* is in use, then :exc:`ValueError` will be raised.

        :param name:
            Method's name.

        :param handler:
            Method's handler.
        """

    @abc.abstractmethod
    def register_namespace(self, ns: 'IMethodHandlerRegistry', prefix: str = None):
        """Attach a nested namespace to this namespace.

        This method will throw a :exc:`ValueError` exception in case of name
        collisions.

        :param ns:
            Namespace object to be attached.

        :param prefix:
            Prefix name to be used for this namespace.

            If given, then all methods from namespace *ns* will be prefixed
            with given value (f.e. method ``bar`` will become method
            ``foo.bar`` if *prefix* is ``foo``).

            If not given, then all methods and nested namespaces from a
            namespace *ns* will be registered directly to this namespace,
            without nesting; methods via :meth:`register_method` method and
            namespaces - via :meth:`register_namespace` method.
        """


@export
class IJSONRPCServer(IClosable, IJSONRPCNotifier, IMethodHandlerRegistry):
    """Base class for JSONRPC protocol servers."""
